import{_ as t,o as i,c as s,a0 as o}from"./chunks/framework.D4fUSYzX.js";const f=JSON.parse('{"title":"The documentation site builds from the docs folder with VitePress","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0018-the-documentation-site-builds-from-the-docs-folder-with-vitepress.md","filePath":"adr/0018-the-documentation-site-builds-from-the-docs-folder-with-vitepress.md"}'),d={name:"adr/0018-the-documentation-site-builds-from-the-docs-folder-with-vitepress.md"};function a(r,e,n,c,l,h){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="the-documentation-site-builds-from-the-docs-folder-with-vitepress" tabindex="-1">The documentation site builds from the docs folder with VitePress <a class="header-anchor" href="#the-documentation-site-builds-from-the-docs-folder-with-vitepress" aria-label="Permalink to &quot;The documentation site builds from the docs folder with VitePress&quot;">​</a></h1><p>Status: accepted.</p><p>The project publishes a documentation site on GitHub Pages for this repository, and its content is written and maintained by agents. We decided the site is built with VitePress directly from the existing <code>docs/</code> folder, so the published site and the source documentation can never disagree. A published subset is exposed (the ADRs, the standards, and guide subfolders), and the internal folders stay in the repository but out of the build.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li>Docusaurus was liked for its flexibility, but its React and MDX toolchain is a larger failure surface for agent-authored content, and the features that justify it (versioned docs, i18n, custom components) are not needed.</li><li>A separate site repository, or a dedicated site folder inside this repository, was rejected because it adds a copy or sync step that can drift from the documentation it is supposed to publish.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The <code>docs/</code> folder is the site source root, and the site config and its build artifacts live inside it.</li><li>ADRs, standards, and guides are public content. The agent instruction, verification, and research folders are repository content only.</li><li>The sidebar is generated from the folder structure at build time. Adding a page is one action: write the file.</li><li>New guide subfolders may be added by agents. New top-level sections are a maintainer decision.</li><li>A CI job runs the site build, and a workflow deploys the build to the <code>gh-pages</code> branch on push to <code>main</code>.</li></ul>',7)])])}const p=t(d,[["render",a]]);export{f as __pageData,p as default};
